def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]

    def repeated(cells):
        seen = set()
        for c in cells:
            if c in seen and c:
                return True
            seen.add(c)
        return False

    row_count = sum(repeated(row) for row in grid)
    col_count = sum(repeated([grid[r][c] for r in range(h)]) for c in range(w))
    do_rows = row_count >= col_count or (row_count >= 2 and col_count >= 2)
    do_cols = col_count >= row_count or (row_count >= 2 and col_count >= 2)

    def process(cells, setter):
        n = len(cells)
        by_color = {}
        for i, c in enumerate(cells):
            if c:
                by_color.setdefault(c, []).append(i)
        for color, pos in by_color.items():
            if len(pos) < 2:
                continue
            # Adjacent occurrences determine the fundamental spacing.
            pos = sorted(pos)
            d = min(b - a for a, b in zip(pos, pos[1:]))
            a, b = pos[0], pos[-1]
            lo, hi = 0, n - 1
            draw_color = color
            others = [(i, cells[i]) for i in range(n)
                      if cells[i] and cells[i] != color]
            for i, c in others:
                if i < a and (a - i) % d == 0:
                    lo = i
                    draw_color = c
                elif i > b and (i - b) % d == 0:
                    hi = i
                    draw_color = c
            first = a
            while first - d >= lo:
                first -= d
            for i in range(first, hi + 1, d):
                setter(i, draw_color)
            for i, c in others:
                if a < i < b:
                    setter(i, color)

    if do_rows:
        for r in range(h):
            process(grid[r], lambda c, v, r=r: out[r].__setitem__(c, v))
    if do_cols:
        for c in range(w):
            process([grid[r][c] for r in range(h)],
                    lambda r, v, c=c: out[r].__setitem__(c, v))
    return out
